import { describe, it, expect, vi } from 'vitest';
import { createChatOrchestrator } from './chatOrchestrator.js';
import { PromptBuilder } from '../infrastructure/builders/promptBuilder.js';
import type { AIProvider, MessageChunk } from '../types/ai.js';
import type { ChatSession } from '../types/session.js';

const promptBuilder = new PromptBuilder({ identity: 'You are a test assistant.' });

const sessionWith = (content: string): ChatSession => ({
  sessionId: 'test-session',
  userId: 'user-1',
  entries: [{ role: 'user', content, timestamp: new Date().toISOString() }],
});

const rejectingWith = (reason: unknown): AIProvider => ({
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw reason;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

describe('ChatOrchestrator onError on non-Error rejections (round test)', () => {
  it('calls onError when a turn rejects with a string', async () => {
    const onError = vi.fn();
    const orchestrator = createChatOrchestrator(
      rejectingWith('string boom'),
      promptBuilder,
      undefined,
      { hooks: { onError } }
    );

    await expect(orchestrator.processMessage(sessionWith('hello'))).rejects.toBe('string boom');

    expect(onError).toHaveBeenCalled();
    const errorArgument = onError.mock.calls[0][1];
    expect(errorArgument).toBeInstanceOf(Error);
    expect(errorArgument.message).toBe('string boom');
    expect(errorArgument.cause).toBe('string boom');
  });
});

